/// <summary>
/// MPJ_5012_RebateProcess
/// Service class to run the update of Rebate Item groups by adding new items
/// </summary>
class METRebateExcludeForPaymentService extends SysOperationServiceBase
{
    const real  RetryNum = 3;
}

Method.Source:
    /// <summary>
    /// MPJ_5012_RebateProcess
    /// Method to exclude the items of the rebate deal for payment.
    /// </summary>
    /// <param name = "_contract"> METRebateExcludeForPaymentContract </param>
    public void processOperation(METRebateExcludeForPaymentContract _contract)
    {
        TAMRebateDeal               rebateDealContract;
        TAMRebateTrans              rebateTrans;
        TAMRebateDateTrans          rebateDateTrans;

        TAMRebateTransId            transIdGlobal, transIdLocal;
        
        Query                       query;
        QueryRun                    queryRun;
        QueryBuildDataSource        qbdsRebateTrans, qbdsRebateDateTrans, qbdsRebateGroupLink, qbdsInventTable;

        const Amount rebateAmountMultiplier = 0.0;
        Set rebateTransIdSet    =   new Set(Types::String);
        boolean useClaimProcess = TAMRebateParameters::find().UseClaimProcess;

        query = new Query();
        rebateDealContract  =   _contract.parmTAMRebateDeal();

        qbdsRebateDateTrans = query.addDataSource(tableNum(TAMRebateDateTrans));
        qbdsRebateDateTrans.addRange(fieldNum(TAMRebateDateTrans, RebateDeal)).value(queryValue(rebateDealContract.RecId));

        qbdsRebateTrans = qbdsRebateDateTrans.addDataSource(tableNum(TAMRebateTrans));
        qbdsRebateTrans.relations(true);
        qbdsRebateTrans.addSortField(fieldNum(TAMRebateTrans, RebateTransId), SortOrder::Ascending);

        qbdsInventTable = qbdsRebateTrans.addDataSource(tableNum(InventTable));
        qbdsInventTable.relations(false);
        qbdsInventTable.addLink(fieldNum(TAMRebateTrans, ItemId), fieldNum(InventTable, ItemId));

        qbdsRebateGroupLink = qbdsInventTable.addDataSource(tableNum(TAMRebateGroupLink));
        qbdsRebateGroupLink.relations(false);
        qbdsRebateGroupLink.linkFields(fieldStr(TAMRebateGroupLink, RefRecId), fieldStr(InventTable, RecId));
        qbdsRebateGroupLink.linkFields(fieldStr(TAMRebateGroupLink, RefTableId), fieldStr(InventTable, TableId));
        qbdsRebateGroupLink.addRange(fieldNum(TAMRebateGroupLink, ModuleInventCustVend)).value(queryValue(ModuleInventCustVend::Invent));
        qbdsRebateGroupLink.addRange(fieldnum(TAMRebateGroupLink, METExcludeForPayment)).value(queryValue(NoYes::Yes));

        queryRun = new QueryRun(query);

        while(queryRun.next())
        {
            rebateTrans     =   queryRun.get(tableNum(TAMRebateTrans));
            rebateDateTrans =   queryRun.get(tableNum(TAMRebateDateTrans));

            try
            {
                ttsbegin;
                rebateTrans.selectForUpdate(true);
                rebateTrans.RebateAmount    =   rebateTrans.RebateAmount * rebateAmountMultiplier;
                rebateTrans.Claimed         =   NoYes::No;
                rebateTrans.modifiedField(fieldNum(TAMRebateTrans, Claimed));
                if(rebateTrans.validateWrite())
                {
                    rebateTrans.update(true);
                    transIdLocal = rebateTrans.RebateTransId;
                    if(transIdGlobal != transIdLocal || !transIdGlobal)
                    {
                        transIdGlobal = transIdLocal;
                        rebateTransIdSet.add(transIdGlobal);
                    }
                }
                ttscommit;
            }            
            catch(Exception::UpdateConflict)
            {
                Info("@MET:METExcludeUpdateConflict", rebateTrans.ItemId);
                throw Exception::UpdateConflictNotRecovered;
            }
            catch(Exception::Deadlock)
            {
                if (xSession::currentRetryCount() >= RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                retry;
            }
            catch(Exception::CLRError)
            {
                System.Exception netExcepn;
                info("@MET:METRebateCLRException");
                netExcepn = CLRInterop::getLastException();
                info(netExcepn.ToString());
            }
            catch(Exception::Error)
            {
                Info("@MET:METRebateError");
            }
        }
        SetEnumerator rebateTransIdEnumerator = rebateTransIdSet.getEnumerator();
        while (rebateTransIdEnumerator.moveNext())
        {
            this.recalcRebateAmountStatic(rebateTransIdEnumerator.current(), useClaimProcess);
        }
    }

/// <summary>
/// Method will recalculate the Rebate amount based on updated Un-Claimed source transactions
/// </summary>
/// <param name = "_rebateTransId">Rebate transaction reference</param>
/// <param name = "_useClaimProcess">Based on this option claim process will be enabled</param>
protected void recalcRebateAmountStatic(TAMRebateTransId _rebateTransId, boolean _useClaimProcess)
{
    TAMRebateDateTrans rebateDateTrans;

    try
    {
        ttsbegin;
        select firstonly forUpdate rebateDateTrans
            where rebateDateTrans.RebateTransId == _rebateTransId
               && !rebateDateTrans.RebatePosted;

        if (rebateDateTrans)
        {
            TAMRebateTrans rebateTrans;

            select sum(CorrectedAmount) from rebateTrans
                where rebateTrans.RebateTransId == _rebateTransId
                   && (!_useClaimProcess
                   ||  rebateDateTrans.RebateTransactionType != TAMRebateTransactionType::Rebate
                   ||  rebateTrans.Claimed)
                   && rebateTrans.CorrectedAmount;

            Amount totalAmount = rebateTrans.CorrectedAmount;

            select sum(RebateAmount) from rebateTrans
                where rebateTrans.RebateTransId == _rebateTransId
                   && (!_useClaimProcess
                   ||  rebateDateTrans.RebateTransactionType != TAMRebateTransactionType::Rebate
                   ||  rebateTrans.Claimed)
                   && !rebateTrans.CorrectedAmount;

            totalAmount += rebateTrans.RebateAmount;

            if (rebateDateTrans.RebateAmount != totalAmount)
            {
                rebateDateTrans.RebateAmount = totalAmount;
                if(rebateDateTrans.validateWrite())
                {
                    rebateDateTrans.update();
                }
            }
        }
        ttscommit;
    }
    catch(Exception::UpdateConflict)
    {
        throw Exception::UpdateConflictNotRecovered;
    }
    catch(Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= RetryNum)
        {
            throw Exception::UpdateConflictNotRecovered;
        }
        retry;
    }
    catch(Exception::CLRError)
    {
        System.Exception netExcepn;
        info("@MET:METRebateCLRException");
        netExcepn = CLRInterop::getLastException();
        info(netExcepn.ToString());
    }
    catch(Exception::Error)
    {
        Info("@MET:METRebateError");
    }
}
